from pathlib import Path
import json
root=Path(__file__).resolve().parents[3];doc=root/'docs/development/watch-design-lab-20261031'
rows=[
('expedition-dial','Expedition dial','How far is this run from its real distance reap?','Tap the dial to focus distance, resources or run duration. Refresh is a local fixture interaction.','Actual saved hero, distance/effective cap and run counts; controlled background trajectory gains when away.','The saved hero, a readable arc and four compact counters.',['Enlarged the selected saved portrait and rounded the actual phone health percentage.','Placed static last-phone health inside the dial and bounded the shared clock region.']),
('living-trail','Living trail','Where am I on this route?','Watch the authored running animation; tap refresh for the one-shot authored Carl arrival.','Distance fraction uses the actual effective cap, never the best retained run. Terrain is a decorative schematic.','A pixel riverbank, moving saved hero and Carl at the distance endpoint.',['Rebuilt the clipped bank from source water tiles and game grass.','Reduced the trail height so distance, endpoint and all counters fit42mm.']),
('combat-watch','Combat watch','What was my last phone health?','Refresh the local fixture presentation; inspect the age beside static phone health.','Every value is a last-phone snapshot, including distance and totals. Health never forecasts or animates as live work.','Hero and last phone health dominate a quiet combat glance.',['Removed excess top space and stamped last phone health with its source age.','Kept all values in the same phone snapshot scope during background states.']),
('harvest-counter','Harvest counter','How much did this run collect, and at what run-average rate?','Toggle totals and run averages in place.','Phone totals divided by the matching phone duration, per minute; never instantaneous rates.','Resource-first display with task and kill tallies.',['Shortened the counter cards so the full44pt average toggle remains visible.','Kept source age explicit and matching totals/duration together.']),
('since-you-left','Since you left','What does the managed trajectory estimate I gained while away?','Inspect the restart and expired variants; counters freeze while restarting and after the horizon.','Eight-column trajectory gains only: tasks, kills, resources, reaps; distance and cap are current trajectory values.','One elapsed reading, four gained counters and current distance.',['Removed duplicate elapsed text and compressed four gains without clipping distance.','Corrected the controlled first-reap cap to214.12 and validated restart/expiry freezes.']),
('run-goal','Run goal','How much remains to my chosen Watch-session goal?','Tap remaining for Crown editing or open Choose goal to change metric and use44pt +/- controls.','Session-only local target. No quests, awards, persistent goals or inferred run identity. Current quantity always uses the last phone snapshot and freezes while away; no accumulation across reaps.','A linear stepped goal track with remaining quantity, current/target and a native editor.',['Compared the segmented arc against a distinct linear stepped goal; selected the clear linear remaining/current/target layout.','Added a native goal editor and rounded remaining distance upward.']),
('skillbook','Skillbook','What are my six actual skill levels?','Tap a skill to pin/unpin it for the lab session. Crown-scroll large text.','Actual skill IDs, levels and source icon art; no unknown XP progress.','Six crisp skill cells in a readable2×3 grid.',['Removed nested scrolling and excess top space.','Fit six44pt tappable cells in the normal42mm first viewport.']),
('run-ribbon','Run ribbon','How do the retained runs vary?','Touch or turn Crown to select a genuine bar; toggle distance/resources; open a receipt.','Last retained global ten, common zero baseline, distinct estimate marks and selected outcome.','A compact run chart with a useful selected receipt.',['Added explicit metric units and outcome icon.','Reduced the chart to keep metric switching and receipt navigation visible.']),
('run-comparison','Run comparison','How do two retained runs compare on matching run-average rates?','Cycle the selected pair and open either receipt. Same-map records are preferred.','Two retained records, map/outcome/duration/distance/resources-per-minute. Mixed estimates visibly qualified; no equipment causality.','Rate delta first, then two compact actionable run cards.',['Moved delta above the cards and added proportional rate bars.','Used shared display precision for both rates and their delta.']),
('map-dossier','Map dossier','What do the retained ten tell me about this map?','Tap or turn Crown to select a map; open its latest retained receipt. Empty maps show honest no-records text.','Latest retained run, recent recorded-only best, current run where applicable, sample count and estimate-qualified recent rate.','Map, last-run distance, recorded best and a recent-rate summary.',['Combined map and latest distance, removed the detached chevron pill and added current run context.','Used matching distance formatting, visible estimate qualification and selectable known no-history maps.'])]
designs=[]
for n,(slug,title,purpose,interaction,data,short,changes) in enumerate(rows,1):
 ident=f'{n:02d}';states=[]
 for size in ['42','46']:
  for name,label in [('large-text','Large type'),('large-scrolled','Large type after native scrolling'),('large-values','Large values'),('beyond-history','Beyond historical best'),('empty','No snapshot'),('town','Town'),('offline','Offline cached'),('away','Phone background'),('restart','Restart pause'),('expired','Estimate expired'),('no-reap','No distance reap'),('no-history','No retained history'),('interaction','Interaction'),('detail','Receipt'),('pinned','Pinned skill'),('goal-editor','Goal editor'),('goal-edited','Edited goal'),('rates','Run averages'),('selected','Selected bar'),('map-empty','Known map with no records'),('town-empty','No current or retained map'),('dimmed','Always On'),('dead','Died'),('reaped','Reaped')]:
   filename=f'captures/{ident}-{size}-{name}.png'
   if (doc/filename).exists():states.append({'title':f'{label} · {size}mm','file':filename})
 clips=[str(p.relative_to(doc)) for p in sorted((doc/'clips').glob(ident+'-*.mp4'))] if (doc/'clips').exists() else []
 designs.append({'id':ident,'slug':slug,'title':title,'purpose':purpose,'interaction':interaction,'data':data,'short':short,'changes':changes,'captures':{size:{'initial':f'captures/{ident}-{size}-initial.png','final':f'captures/{ident}-{size}-final.png'} for size in ['42','46']},'states':states,'clip':next((c for c in clips if 'foreground' in c), clips[0] if clips else None),'clips':clips})
manifest={'provenance':'Native Watch-only simulator fixture prototype, not production transport or a deployed Watch update. Real game art and saved-character baseline; controlled scenario/history variants explicitly documented in Prototypes/WatchDesignLab/FixtureProvenance.json. Raw simulator PNGs preserved.','designs':designs}
(doc/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
